*
 * DELETE /admin/pages/{page_id}.json
 *
 * Examples:
 *
 *      insales.removePage({
 *        token: '1234567890',
 *        url: 'shop-test.myinsales.ru',
 *        pageid: '1'
 *      }).then(response => {
 *        console.info(response.data);
 *      }).catch(err => {
 *        console.error(err);
 *      });
 * Output:
 *
 *      {
 *        "status": "ok"
 *      }
